def ref(p):
 b=p.read_bytes();return {'path':p.as_posix(),'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b)}
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def write(name,x):
 b=(json.dumps(x,ensure_ascii=False,indent=2)+'\n').encode('utf-8') if not isinstance(x,str) else x.encode('utf-8')
 with (O/name).open('xb') as f:f.write(b)
 return ref(O/name)
def lines(p,needle):
 a=p.read_text(encoding='utf-8').splitlines();found=[i+1 for i,s in enumerate(a) if needle in s]
 assert found,(p,needle)
 return {'ref':ref(p),'locator':{'matching_lines':found,'literal':needle}}
